-- Everything the weekly check needs from Supabase, as three files (run by the read-db task):
--   sheet.csv   every establishment, in the old Google Sheet's columns, so the weekly tools work unchanged.
--               days/start/end/deals are filled when the bar's happy hour came from a call, the owner or a hand
--               entry (those win over the website, like the sheet used to).
--   review.csv  what's waiting for a decision: held happy hours from calls, and calls a person should look at.
--               No staff names, transcripts or callback details (the job log is public).
--   db.csv      what the website publishes (same as tools/site_export.sql).
\copy (select e.name, e.neighborhood, e.address, e.zip, e.type, e.license_no, case when e.status = 'closed' then 'closed' when e.status = 'no_happy_hour' then 'no hh' else '' end as status, e.website, e.phone, e.instagram, '' as result, '' as "suggested name", '' as "suggested website", (select array_to_string(h.days, ',') from happy_hours h where h.establishment_id = e.id and h.review_status = 'live' and h.source <> 'website' order by h.start_time limit 1) as days, (select to_char(h.start_time, 'HH24:MI') from happy_hours h where h.establishment_id = e.id and h.review_status = 'live' and h.source <> 'website' order by h.start_time limit 1) as start, (select to_char(h.end_time, 'HH24:MI') from happy_hours h where h.establishment_id = e.id and h.review_status = 'live' and h.source <> 'website' order by h.start_time limit 1) as "end", (select array_to_string(h.deals, '|') from happy_hours h where h.establishment_id = e.id and h.review_status = 'live' and h.source <> 'website' order by h.start_time limit 1) as deals, e.notes, e.status as db_status, e.id as establishment_id from establishments e order by e.name) to 'sheet.csv' with (format csv, header)
\copy (select 'happy_hour' as kind, h.id, e.name as bar, e.address, e.neighborhood, e.website, to_char(c.called_at, 'YYYY-MM-DD') as called_on, h.confidence, array_to_string(h.days, ',') || ' ' || to_char(h.start_time, 'HH24:MI') || '-' || to_char(h.end_time, 'HH24:MI') || coalesce(': ' || nullif(array_to_string(h.deals, ' | '), ''), '') as reported, public.listed_summary(e.id) as listed_now, h.review_note as reason from happy_hours h join establishments e on e.id = h.establishment_id left join calls c on c.id = h.call_id where h.review_status = 'needs_review' union all select 'call', c.id, coalesce(e.name, c.payload->>'bar_name'), coalesce(e.address, c.payload->>'address'), e.neighborhood, e.website, to_char(c.called_at, 'YYYY-MM-DD'), c.confidence, 'outcome ' || coalesce(c.outcome, '?') || ', happy hour ' || coalesce(c.has_happy_hour, '?') || coalesce(', other specials: ' || nullif(c.payload->>'other_specials', ''), ''), public.listed_summary(e.id), coalesce(c.review_note, 'Needs a look') from calls c left join establishments e on e.id = c.establishment_id where not c.processed and not exists (select 1 from happy_hours h where h.call_id = c.id and h.review_status = 'needs_review') order by 1, 3) to 'review.csv' with (format csv, header)
\i tools/site_export.sql
select 'Calls this week: ' || count(*) filter (where called_at > now() - interval '7 days') || ', all time: ' || count(*) from calls;
select 'Waiting for review: ' || (select count(*) from happy_hours where review_status = 'needs_review') || ' happy hours, ' || (select count(*) from calls c where not c.processed and not exists (select 1 from happy_hours h where h.call_id = c.id and h.review_status = 'needs_review')) || ' calls';
select 'Call queue: ' || count(*) || ' bars with a phone number (' || count(*) filter (where last_called is null) || ' never called)' from call_queue;
